(() => {
  const DONATION_URL =
    "https://pucuk-9d1d6-default-rtdb.asia-southeast1.firebasedatabase.app/donasi.json";

  const QRIS_IMAGE = "data:image/jpeg;base64,";

  // =========================
  // STYLE
  // =========================
  const style = document.createElement("style");

  style.textContent = `
    #donation-fab {
      position: fixed;
      right: 16px;
      bottom: 16px;
      z-index: 9998;
      border: 1px solid rgba(141,232,255,.45);
      background: linear-gradient(135deg, #101a29, #05080e);
      color: #8de8ff;
      padding: 9px 14px;
      border-radius: 999px;
      font-size: 13px;
      font-weight: 700;
      cursor: pointer;
      box-shadow:
        0 0 12px rgba(90,207,255,.18),
        inset 0 0 8px rgba(90,207,255,.05);
      transition: .2s ease;
      user-select: none;
      -webkit-tap-highlight-color: transparent;
    }

    #donation-fab:active {
      transform: scale(.95);
    }

    /* BACKDROP BLUR */
    #donation-backdrop {
      position: fixed;
      inset: 0;
      z-index: 9997;
      display: none;
      background: rgba(0,0,0,.38);
      backdrop-filter: blur(5px);
      -webkit-backdrop-filter: blur(5px);
    }

    /* POPUP AWAL */
    #donation-popup {
      position: fixed;
      right: 16px;
      bottom: 62px;
      width: 250px;
      z-index: 9999;
      display: none;
      box-sizing: border-box;
      padding: 14px;
      border-radius: 15px;
      border: 1px solid rgba(141,232,255,.28);
      background:
        linear-gradient(
          145deg,
          rgba(16,26,41,.98),
          rgba(5,8,14,.98)
        );
      color: #eafaff;
      box-shadow:
        0 10px 35px rgba(0,0,0,.65),
        0 0 18px rgba(90,207,255,.10);
      animation: donationPopupIn .18s ease;
    }

    @keyframes donationPopupIn {
      from {
        opacity: 0;
        transform: translateY(8px) scale(.97);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    #donation-popup-title {
      color: #8de8ff;
      font-size: 15px;
      font-weight: 800;
      margin-bottom: 7px;
    }

    #donation-popup-text {
      font-size: 12px;
      line-height: 1.5;
      color: #c9dce3;
      margin-bottom: 12px;
    }

    #donation-now {
      width: 100%;
      border: 0;
      border-radius: 10px;
      padding: 10px;
      background: linear-gradient(135deg, #5acfff, #8de8ff);
      color: #031018;
      font-weight: 800;
      font-size: 12px;
      cursor: pointer;
      box-shadow: 0 0 12px rgba(90,207,255,.20);
    }

    #donation-now:active {
      transform: scale(.98);
    }

    /* FORM DONASI */
    #donation-layer {
      position: fixed;
      inset: 0;
      z-index: 10000;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 12px;
      box-sizing: border-box;
      background: rgba(0,0,0,.60);
      backdrop-filter: blur(5px);
      -webkit-backdrop-filter: blur(5px);
    }

    #donation-box {
      width: min(330px, 94vw);
      max-height: 94vh;
      overflow: hidden;
      box-sizing: border-box;
      border-radius: 17px;
      border: 1px solid rgba(141,232,255,.30);
      background: linear-gradient(145deg, #101a29, #05080e);
      box-shadow:
        0 15px 45px rgba(0,0,0,.75),
        0 0 20px rgba(90,207,255,.10);
      padding: 13px;
      color: #eafaff;
      animation: donationBoxIn .2s ease;
    }

    @keyframes donationBoxIn {
      from {
        opacity: 0;
        transform: scale(.95);
      }
      to {
        opacity: 1;
        transform: scale(1);
      }
    }

    #donation-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 8px;
    }

    #donation-title {
      color: #8de8ff;
      font-size: 16px;
      font-weight: 800;
    }

    #donation-close {
      width: 27px;
      height: 27px;
      border: 0;
      border-radius: 50%;
      background: rgba(255,255,255,.06);
      color: #cfe8ef;
      font-size: 18px;
      line-height: 27px;
      text-align: center;
      cursor: pointer;
    }

    #donation-desc {
      font-size: 11px;
      line-height: 1.4;
      color: #aebfc6;
      margin-bottom: 9px;
    }

    #donation-qris-wrap {
      text-align: center;
      margin-bottom: 8px;
    }

    #donation-qris {
      width: 250px;
      height: 250px;
      object-fit: contain;
      display: block;
      margin: 0 auto;
      border-radius: 9px;
      background: white;
      padding: 5px;
      box-sizing: border-box;
    }

    #donation-qris-label {
      font-size: 10px;
      color: #8de8ff;
      margin-top: 5px;
    }

    .donation-field {
      margin-top: 7px;
    }

    .donation-field label {
      display: block;
      font-size: 10px;
      color: #8de8ff;
      margin-bottom: 4px;
    }

    .donation-field input,
    .donation-field textarea {
      width: 100%;
      box-sizing: border-box;
      border: 1px solid rgba(141,232,255,.18);
      outline: none;
      border-radius: 8px;
      background: rgba(0,0,0,.28);
      color: #eafaff;
      font-size: 11px;
      padding: 8px 9px;
      font-family: inherit;
    }

    .donation-field input:focus,
    .donation-field textarea:focus {
      border-color: rgba(141,232,255,.55);
      box-shadow: 0 0 8px rgba(90,207,255,.10);
    }

    .donation-field textarea {
      height: 48px;
      resize: none;
    }

    #donation-submit {
      width: 100%;
      margin-top: 9px;
      border: 0;
      border-radius: 9px;
      padding: 9px;
      background: linear-gradient(135deg, #5acfff, #8de8ff);
      color: #031018;
      font-size: 11px;
      font-weight: 800;
      cursor: pointer;
    }

    #donation-submit:disabled {
      opacity: .55;
      cursor: wait;
    }

    /* CUSTOM ALERT */
    #donation-alert-layer {
      position: fixed;
      inset: 0;
      z-index: 11000;
      display: none;
      align-items: center;
      justify-content: center;
      background: rgba(0,0,0,.55);
      backdrop-filter: blur(5px);
      -webkit-backdrop-filter: blur(5px);
      padding: 15px;
      box-sizing: border-box;
    }

    #donation-alert-box {
      width: min(280px, 90vw);
      box-sizing: border-box;
      padding: 16px;
      border-radius: 15px;
      border: 1px solid rgba(141,232,255,.30);
      background: linear-gradient(145deg, #101a29, #05080e);
      color: #eafaff;
      text-align: center;
      box-shadow: 0 15px 45px rgba(0,0,0,.7);
    }

    #donation-alert-icon {
      font-size: 25px;
      margin-bottom: 6px;
    }

    #donation-alert-title {
      color: #8de8ff;
      font-size: 14px;
      font-weight: 800;
      margin-bottom: 5px;
    }

    #donation-alert-message {
      color: #c6d9df;
      font-size: 11px;
      line-height: 1.5;
      margin-bottom: 11px;
    }

    #donation-alert-ok {
      width: 100%;
      border: 0;
      border-radius: 8px;
      padding: 8px;
      background: linear-gradient(135deg, #5acfff, #8de8ff);
      color: #031018;
      font-size: 11px;
      font-weight: 800;
      cursor: pointer;
    }
  `;

  document.head.appendChild(style);

  // =========================
  // BACKDROP
  // =========================
  const backdrop = document.createElement("div");
  backdrop.id = "donation-backdrop";
  document.body.appendChild(backdrop);

  // =========================
  // FLOATING BUTTON
  // =========================
  const fab = document.createElement("button");
  fab.id = "donation-fab";
  fab.type = "button";
  fab.textContent = "☕ Donasi";
  document.body.appendChild(fab);

  // =========================
  // POPUP AWAL
  // =========================
  const popup = document.createElement("div");
  popup.id = "donation-popup";

  popup.innerHTML = `
    <div id="donation-popup-title">
      ❤️ Dukung KIWOLASU
    </div>

    <div id="donation-popup-text">
      Kalau script ini bermanfaat bagi anda , anda bisa memberikan
      dukungan melalui donasi. sekecil apapun donasi anda sudah cukup membuat kami semangat untuk terus konsisten update 
    </div>

    <button id="donation-now" type="button">
      ❤️ Donasi Sekarang
    </button>
  `;

  document.body.appendChild(popup);

  // =========================
  // DONATION LAYER
  // =========================
  const layer = document.createElement("div");
  layer.id = "donation-layer";

  layer.innerHTML = `
    <div id="donation-box">

      <div id="donation-header">
        <div id="donation-title">
          ❤️ Donasi
        </div>

        <button id="donation-close" type="button">
          ×
        </button>
      </div>

      <div id="donation-desc">
        Scan QRIS di bawah untuk memberikan dukungan.
      </div>

      <div id="donation-qris-wrap">
        <img
          id="donation-qris"
          src="${QRIS_IMAGE}"
          alt="QRIS Donasi"
        >

        <div id="donation-qris-label">
          KIWOLASU
        </div>
      </div>

      <div class="donation-field">
        <label>Nama</label>
        <input
          id="donation-name"
          type="text"
          maxlength="50"
          placeholder="Nama / Anonim"
        >
      </div>

      <div class="donation-field">
        <label>Nominal Donasi</label>
        <input
          id="donation-amount"
          type="number"
          min="1"
          inputmode="numeric"
          placeholder="Contoh: 1000"
        >
      </div>

      <div class="donation-field">
        <label>Pesan / Kritik / Saran</label>
        <textarea
          id="donation-message"
          maxlength="300"
          placeholder="Tulis pesan..."
        ></textarea>
      </div>

      <button id="donation-submit" type="button">
        ✓ Kirim Dukungan
      </button>

    </div>
  `;

  document.body.appendChild(layer);

  // =========================
  // CUSTOM ALERT
  // =========================
  const alertLayer = document.createElement("div");
  alertLayer.id = "donation-alert-layer";

  alertLayer.innerHTML = `
    <div id="donation-alert-box">

      <div id="donation-alert-icon">
        ❤️
      </div>

      <div id="donation-alert-title">
        Terima kasih!
      </div>

      <div id="donation-alert-message">
        Dukungan kamu sangat berarti 🙏
      </div>

      <button id="donation-alert-ok" type="button">
        OK
      </button>

    </div>
  `;

  document.body.appendChild(alertLayer);

  // =========================
  // ELEMENT
  // =========================
  const donationNow =
    document.getElementById("donation-now");

  const donationClose =
    document.getElementById("donation-close");

  const donationSubmit =
    document.getElementById("donation-submit");

  const donationName =
    document.getElementById("donation-name");

  const donationAmount =
    document.getElementById("donation-amount");

  const donationMessage =
    document.getElementById("donation-message");

  const alertOk =
    document.getElementById("donation-alert-ok");

  // =========================
  // POPUP OPEN / CLOSE
  // =========================
  function openDonationPopup() {
    popup.style.display = "block";
    backdrop.style.display = "block";
  }

  function closeDonationPopup() {
    popup.style.display = "none";
    backdrop.style.display = "none";
  }

  // =========================
  // FLOATING BUTTON
  // =========================
  fab.addEventListener("click", () => {
    const isOpen = popup.style.display === "block";

    if (isOpen) {
      closeDonationPopup();
    } else {
      openDonationPopup();
    }
  });

  // =========================
  // CLICK BACKDROP
  // =========================
  backdrop.addEventListener("click", () => {
    closeDonationPopup();
  });

  // =========================
  // OPEN FORM
  // =========================
  donationNow.addEventListener("click", () => {
    closeDonationPopup();

    layer.style.display = "flex";
  });

  // =========================
  // CLOSE FORM
  // =========================
  donationClose.addEventListener("click", () => {
    layer.style.display = "none";
  });

  // Klik area luar box untuk menutup
  layer.addEventListener("click", (e) => {
    if (e.target === layer) {
      layer.style.display = "none";
    }
  });

  // =========================
  // CUSTOM ALERT
  // =========================
  function showAlert(
    title,
    message,
    icon = "❤️"
  ) {
    document.getElementById(
      "donation-alert-title"
    ).textContent = title;

    document.getElementById(
      "donation-alert-message"
    ).textContent = message;

    document.getElementById(
      "donation-alert-icon"
    ).textContent = icon;

    alertLayer.style.display = "flex";
  }

  function closeAlert() {
    alertLayer.style.display = "none";
  }

  alertOk.addEventListener("click", closeAlert);

  alertLayer.addEventListener("click", (e) => {
    if (e.target === alertLayer) {
      closeAlert();
    }
  });

  // =========================
  // FORMAT NOMINAL
  // =========================
  donationAmount.addEventListener("input", () => {
    let value = donationAmount.value;

    value = value.replace(/[^0-9]/g, "");

    donationAmount.value = value;
  });

  // =========================
  // SUBMIT DONASI
  // =========================
  donationSubmit.addEventListener("click", async () => {

    const name =
      donationName.value.trim();

    const amount =
      Number(donationAmount.value);

    const message =
      donationMessage.value.trim();

    // Validasi nominal
    if (!amount || amount <= 0) {
      showAlert(
        "Nominal belum diisi",
        "Silakan masukkan nominal donasi terlebih dahulu.",
        "⚠️"
      );

      donationAmount.focus();
      return;
    }

    // Disable tombol
    donationSubmit.disabled = true;
    donationSubmit.textContent = "⏳ Mengirim...";

    try {

      const data = {
        nama: name || "Anonim",
        nominal: amount,
        pesan: message || "",
        waktu: Date.now()
      };

      const response = await fetch(
        DONATION_URL,
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json"
          },

          body: JSON.stringify(data)
        }
      );

      if (!response.ok) {
        throw new Error(
          "Firebase request failed"
        );
      }

      // Reset form
      donationName.value = "";
      donationAmount.value = "";
      donationMessage.value = "";

      layer.style.display = "none";

      showAlert(
        "Terima kasih atas dukungannya ❤️",
        "dukungan kamu berhasil dikirim. Terima kasih sudah mendukung KIWOLASU 🙏",
        "❤️"
      );

    } catch (error) {

      console.error(
        "Donasi error:",
        error
      );

      showAlert(
        "Gagal mengirim",
        "belum berhasil dikirim. Silakan coba lagi.",
        "⚠️"
      );

    } finally {

      donationSubmit.disabled = false;
      donationSubmit.textContent =
        "✓ Kirim Dukungan";
    }
  });

})();